import{_ as i,a0 as o,w as d,s as r,ao as l,I as p,x as a,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"/dev/[u]random：对熵的解释 | LCTT x X-CMD","titleTemplate":false,"description":"/dev/[u]random：对熵的解释 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"/dev/[u]random：对熵的解释 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"/dev/[u]random：对熵的解释 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20171101 -dev-urandom- entropy explained","title":"/dev/[u]random：对熵的解释","tag":"201805","desc":""},"relativePath":"201805/20171101 -dev-urandom- entropy explained.md","filePath":"[post].md"}'),g={name:"201805/20171101 -dev-urandom- entropy explained.md"};function h(m,s,u,c,v,b){const n=o("Link");return d(),r("div",null,[s[19]||(s[19]=l(`<h1 id="dev-u-random-对熵的解释" tabindex="-1">/dev/[u]random：对熵的解释 <a class="header-anchor" href="#dev-u-random-对熵的解释" aria-label="Permalink to “/dev/[u]random：对熵的解释”">​</a></h1><h3 id="熵" tabindex="-1">熵 <a class="header-anchor" href="#熵" aria-label="Permalink to “熵”">​</a></h3><p>当谈到 <code>/dev/random</code> 和 <code>/dev/urandom</code> 的主题时，你总是会听到这个词：“<ruby>熵<rt>Entropy</rt></ruby>”。每个人对此似乎都有自己的比喻。那为我呢？我喜欢将熵视为“随机果汁”。它是果汁，随机数需要它变得更随机。</p><p>如果你曾经生成过 SSL 证书或 GPG 密钥，那么可能已经看到过像下面这样的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>We need to generate a lot of random bytes. It is a good idea to perform</span></span>
<span class="line"><span>some other action (type on the keyboard, move the mouse, utilize the</span></span>
<span class="line"><span>disks) during the prime generation; this gives the random number</span></span>
<span class="line"><span>generator a better chance to gain enough entropy.</span></span>
<span class="line"><span>++++++++++..+++++.+++++++++++++++.++++++++++...+++++++++++++++...++++++</span></span>
<span class="line"><span>+++++++++++++++++++++++++++++.+++++..+++++.+++++.+++++++++++++++++++++++++&gt;.</span></span>
<span class="line"><span>++++++++++&gt;+++++...........................................................+++++</span></span>
<span class="line"><span>Not enough random bytes available. Please do some other work to give</span></span>
<span class="line"><span>the OS a chance to collect more entropy! (Need 290 more bytes)</span></span></code></pre></div><p>通过在键盘上打字并移动鼠标，你可以帮助生成熵或随机果汁。</p><p>你可能会问自己……为什么我需要熵？以及为什么它对于随机数真的变得随机如此重要？那么，假设我们的熵的来源仅限于键盘、鼠标和磁盘 IO 的数据。但是我们的系统是一个服务器，所以我知道没有鼠标和键盘输入。这意味着唯一的因素是你的 IO。如果它是一个单独的、几乎不使用的磁盘，你将拥有较低的熵。这意味着你的系统随机的能力很弱。换句话说，我可以玩概率游戏，并大幅减少破解 ssh 密钥或者解密你认为是加密会话的时间。</p>`,7)),p("p",null,[s[1]||(s[1]=a("好的，但这是很难实现的对吧？不，实际上并非如此。看看这个 ",-1)),e(n,{href:"http://jhurani.com/linux/2017/11/01/%22https://jblevins.org/log/ssh-vulnkey%22"},{default:t(()=>[...s[0]||(s[0]=[a("Debian OpenSSH 漏洞",-1)])]),_:1}),s[2]||(s[2]=a("。这个特定的问题是由于某人删除了一些负责添加熵的代码引起的。有传言说，他们因为它导致 valgrind 发出警告而删除了它。然而，在这样做的时候，随机数现在少了很多随机性。事实上，熵少了很多，因此暴力破解变成了一个可行的攻击向量。",-1))]),s[20]||(s[20]=l(`<p>希望到现在为止，我们理解了熵对安全性的重要性。无论你是否意识到你正在使用它。</p><h3 id="dev-random-和-dev-urandom" tabindex="-1">/dev/random 和 /dev/urandom <a class="header-anchor" href="#dev-random-和-dev-urandom" aria-label="Permalink to “/dev/random 和 /dev/urandom”">​</a></h3><p><code>/dev/urandom</code> 是一个伪随机数生成器，缺乏熵它也<strong>不会</strong>停止。</p><p><code>/dev/random</code> 是一个真随机数生成器，它会在缺乏熵的时候停止。</p><p>大多数情况下，如果我们正在处理实际的事情，并且它不包含你的核心信息，那么 <code>/dev/urandom</code> 是正确的选择。否则，如果就使用 <code>/dev/random</code>，那么当系统的熵耗尽时，你的程序就会变得有趣。无论它直接失败，或只是挂起——直到它获得足够的熵，这取决于你编写的程序。</p><h3 id="检查熵" tabindex="-1">检查熵 <a class="header-anchor" href="#检查熵" aria-label="Permalink to “检查熵”">​</a></h3><p>那么，你有多少熵？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@testbox test]# cat /proc/sys/kernel/random/poolsize</span></span>
<span class="line"><span>4096</span></span>
<span class="line"><span>[root@testbox test]# cat /proc/sys/kernel/random/entropy_avail</span></span>
<span class="line"><span>2975</span></span></code></pre></div><p><code>/proc/sys/kernel/random/poolsize</code>，说明熵池的大小（以位为单位）。例如：在停止抽水之前我们应该储存多少随机果汁。<code>/proc/sys/kernel/random/entropy_avail</code> 是当前池中随机果汁的数量（以位为单位）。</p><h3 id="我们如何影响这个数字" tabindex="-1">我们如何影响这个数字？ <a class="header-anchor" href="#我们如何影响这个数字" aria-label="Permalink to “我们如何影响这个数字？”">​</a></h3><p>这个数字可以像我们使用它一样耗尽。我可以想出的最简单的例子是将 <code>/dev/random</code> 定向到 <code>/dev/null</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@testbox test]# cat /dev/random &gt; /dev/null &amp;</span></span>
<span class="line"><span>[1] 19058</span></span>
<span class="line"><span>[root@testbox test]# cat /proc/sys/kernel/random/entropy_avail</span></span>
<span class="line"><span>0</span></span>
<span class="line"><span>[root@testbox test]# cat /proc/sys/kernel/random/entropy_avail</span></span>
<span class="line"><span>1</span></span></code></pre></div>`,12)),p("p",null,[s[4]||(s[4]=a("影响这个最简单的方法是运行 ",-1)),e(n,{href:"http://www.issihosts.com/haveged/"},{default:t(()=>[...s[3]||(s[3]=[a("Haveged",-1)])]),_:1}),s[5]||(s[5]=a("。Haveged 是一个守护进程，它使用处理器的“抖动”将熵添加到系统熵池中。安装和基本设置非常简单。",-1))]),s[21]||(s[21]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@b08s02ur ~]# systemctl enable haveged</span></span>
<span class="line"><span>Created symlink from /etc/systemd/system/multi-user.target.wants/haveged.service to /usr/lib/systemd/system/haveged.service.</span></span>
<span class="line"><span>[root@b08s02ur ~]# systemctl start haveged</span></span></code></pre></div><p>在流量相对中等的机器上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@testbox ~]# pv /dev/random &gt; /dev/null </span></span>
<span class="line"><span>  40 B 0:00:15 [   0 B/s] [                    &lt;=&gt;                                                                                                                                                      ]</span></span>
<span class="line"><span>  52 B 0:00:23 [   0 B/s] [                           &lt;=&gt;                                                                                                                                               ]</span></span>
<span class="line"><span>  58 B 0:00:25 [5.92 B/s] [                              &lt;=&gt;                                                                                                                                            ]</span></span>
<span class="line"><span>  64 B 0:00:30 [6.03 B/s] [                                  &lt;=&gt;                                                                                                                                        ]</span></span>
<span class="line"><span>^C</span></span>
<span class="line"><span>[root@testbox ~]# systemctl start haveged</span></span>
<span class="line"><span>[root@testbox ~]# pv /dev/random &gt; /dev/null </span></span>
<span class="line"><span>7.12MiB 0:00:05 [1.43MiB/s] [                &lt;=&gt;                                                                                                                                                        ]</span></span>
<span class="line"><span>15.7MiB 0:00:11 [1.44MiB/s] [                                    &lt;=&gt;                                                                                                                                    ]</span></span>
<span class="line"><span>27.2MiB 0:00:19 [1.46MiB/s] [                                                               &lt;=&gt;                                                                                                         ]</span></span>
<span class="line"><span>  43MiB 0:00:30 [1.47MiB/s] [                                                                                                    &lt;=&gt;                                                                    ]</span></span>
<span class="line"><span>^C</span></span></code></pre></div><p>使用 <code>pv</code> 我们可以看到我们通过管道传递了多少数据。正如你所看到的，在运行 <code>haveged</code> 之前，我们是 2.1 位/秒（B/s）。而在开始运行 <code>haveged</code> 之后，加入处理器的抖动到我们的熵池中，我们得到大约 1.5MiB/秒。</p><hr>`,5)),p("p",null,[s[7]||(s[7]=a("via: ",-1)),e(n,{href:"http://jhurani.com/linux/2017/11/01/entropy-explained.html"},{default:t(()=>[...s[6]||(s[6]=[a("http://jhurani.com/linux/2017/11/01/entropy-explained.html",-1)])]),_:1})]),p("p",null,[s[11]||(s[11]=a("作者：",-1)),e(n,{href:"https://jblevins.org/log/ssh-vulnkey"},{default:t(()=>[...s[8]||(s[8]=[a("James J",-1)])]),_:1}),s[12]||(s[12]=a(" 译者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:t(()=>[...s[9]||(s[9]=[a("geekpi",-1)])]),_:1}),s[13]||(s[13]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[16]||(s[16]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[14]||(s[14]=[a("LCTT",-1)])]),_:1}),s[17]||(s[17]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[15]||(s[15]=[a("Linux中国",-1)])]),_:1}),s[18]||(s[18]=a(" 荣誉推出",-1))])])}const x=i(g,[["render",h]]);export{f as __pageData,x as default};
